        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "Bereits im 18. Jahrhundert, von der Gegenwart zu schweigen, war der Gang der Wissenschaft wie des Glaubens nicht so sehr durch den Willen zum Guten, als durch das Interesse der Macht bedingt.", Author = "Max Horkheimer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "Die Mutter, die einen Beruf ausübt, ist etwas völlig anderes als die Mutter, deren Lebensaufgabe die Erziehung der Kinder war. Der Beruf verdinglicht ihre Gedanken. Dazu kommt noch etwas anderes. Sie ist gleichberechtigt. Sie strahlt, von Ausnahmen abgesehen, nicht mehr die Liebe aus wie vorher.", Author = "Max Horkheimer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "Es gibt keine Definition der Philosophie. Ihre Definition ist identisch mit der expliziten Darstellung dessen, was sie zu sagen hat.", Author = "Max Horkheimer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "Zivilisation bestand weitgehend in der Bildung, das heißt Hineinbildung moralischer Gebote in den Menschen. Je tiefer einem durch Herkunft und Erziehung menschliches Verhalten zur Natur geworden war desto mehr Seele wurde ihm zugesprochen. Achtung vor dem Nächsten, Verantwortungsgefühl, Fähigkeit zur Freundschaft und zur Liebe waren in Moral mit eingeschlossen. Indem der Fortschritt Leben straffer ordnet, das Verhalten reguliert, Phantasie durch zweckvolles, systematisches Vorgehen, positive Affekte durch sichere Reaktionen, Gefühle durch Ratio ersetzt, gleichsam in der Rückschau, ist Seele nunmehr zum emphatischen Begriff geworden, zum Gegensatz der Kälte des auf Technik, schließlich zur Gefolgschaft ausgerichteten Subjekts. Die von Emotionen abgelöste Ratio schlägt um und wird zum Gegenteil von Anima.", Author = "Max Horkheimer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "Philosophie verliert schon deshalb ihren Reiz, weil sie selbst zum Fach geworden ist, nur mit dem Unterschied, daß es niemand so recht brauchen kann.", Author = "Max Horkheimer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "Die Entwicklung einer differenzierten autonomen Person wird um so seltener, als sie nicht mehr im selben Maß wirtschaftlich gefordert, ja beim Fortkommen zum Hemmnis wird.", Author = "Max Horkheimer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "In zahlreichen theoretischen Arbeiten des Instituts für Sozialforschung wurde versucht, die Wechselwirkung von Gesellschaft und Psychologie weiter zu verfolgen. Stets freilich haben wir den gesellschaftlichen Druck — das, was Freud selbst „Lebensnot” nannte — als das Primäre betrachtet.", Author = "Max Horkheimer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "Technische Rationalität heute ist die Rationalität der Herrschaft selbst.", Author = "Max Horkheimer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "Wer aber vom Kapitalismus nicht reden will, sollte auch vom Faschismus schweigen.", Author = "Max Horkheimer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Max_Horkheimer", Text = "Wenn man das Entsetzen der heutigen Welt über die Lustmorde, besonders über Angriffe auf Kinder erfährt, könnte man glauben, dass ihr das Menschenleben und die gesunde Entwicklung des Individuums heilig wäre.", Author = "Max Horkheimer" },
